  doom = "~/.config/emacs/bin/doom";

  # Host-specific: kubernetes (galvatron uses kubectx/kubens, not kswitch)
  k = "kubectl";
  kx = "kubectx";
  kn = "kubens";

  # Restart WSLg compositor without full wsl --shutdown
  # Absolute path: wsl.exe is a Windows binary and the interop PATH is not
  # appended under systemd mode, so bare "wsl.exe" does not resolve.
  # --cd / : wsl.exe otherwise tries to translate the caller's cwd (a NixOS-
  # distro path) into a UNC path for the --system distro, which has no such
  # mapping and fails with "Failed to translate '\\wsl.localhost\...'".
  restart-wslg = ''/mnt/c/Windows/System32/wsl.exe --system --cd / sh -c "pkill -9 weston"'';
};

# plocate `locate`, updated on a systemd timer (Persistent, so a missed
# overnight run catches up on next boot — this box is often off at 02:15).
services.locate = {
  enable = true;
  package = pkgs.plocate;
];

wsl = {
  enable = true;
  useWindowsDriver = true;
  wslConf.automount.root = "/mnt";
  defaultUser = "sme";
  startMenuLaunchers = true;

  # Windows %PATH% otherwise gets appended to $PATH wholesale (see
  # nixos-wsl's modules/interop.nix), adding ~40 /mnt/c/... entries backed
  # by the slow 9p/drvfs interop filesystem. fast-syntax-highlighting does
  # a command-validity check on every keystroke, which for any unrecognized
  # word means scanning all of $PATH to conclude "not found" -- walking
  # those slow Windows dirs made every such keystroke cost ~250ms (profiled
  # via zprof + a wrapped self-insert ZLE widget + tmux round-trip timing).
  # The handful of Windows binaries actually used interactively (clip.exe,
  # explorer.exe, powershell.exe, wsl.exe) are referenced by absolute path
  # instead (see home/sme/galvatron-wsl.nix and restart-wslg below).
  interop.includePath = false;
};

